export default "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, user-scalable=no\" />\n    <title>Neon Breakout</title>\n    <style>\n      * { margin: 0; padding: 0; box-sizing: border-box; }\n\n      :root {\n        --neon-cyan: #00f0ff;\n        --neon-pink: #ff2e93;\n        --neon-green: #39ff14;\n        --neon-yellow: #ffe600;\n        --neon-orange: #ff6b00;\n        --bg-dark: #0a0a1a;\n        --bg-panel: rgba(15, 15, 35, 0.85);\n      }\n\n      html, body {\n        width: 100%;\n        height: 100%;\n        overflow: hidden;\n        background: var(--bg-dark);\n        font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;\n        color: #fff;\n        user-select: none;\n        -webkit-user-select: none;\n      }\n\n      #game-container {\n        position: relative;\n        width: 100vw;\n        height: 100vh;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        background:\n          radial-gradient(ellipse at 20% 30%, rgba(0, 240, 255, 0.08), transparent 50%),\n          radial-gradient(ellipse at 80% 70%, rgba(255, 46, 147, 0.08), transparent 50%),\n          var(--bg-dark);\n      }\n\n      canvas {\n        display: block;\n        border-radius: 12px;\n        box-shadow:\n          0 0 60px rgba(0, 240, 255, 0.15),\n          0 0 120px rgba(255, 46, 147, 0.08),\n          inset 0 0 0 2px rgba(255, 255, 255, 0.05);\n        background: rgba(8, 8, 20, 0.9);\n        touch-action: none;\n      }\n\n      /* HUD */\n      #hud {\n        position: absolute;\n        top: 16px;\n        left: 50%;\n        transform: translateX(-50%);\n        display: flex;\n        gap: 32px;\n        z-index: 10;\n        pointer-events: none;\n        font-size: 15px;\n        letter-spacing: 1px;\n        text-transform: uppercase;\n      }\n\n      .hud-item {\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        gap: 2px;\n      }\n\n      .hud-label {\n        font-size: 10px;\n        color: rgba(255, 255, 255, 0.4);\n        letter-spacing: 2px;\n      }\n\n      .hud-value {\n        font-size: 20px;\n        font-weight: 700;\n        text-shadow: 0 0 12px currentColor;\n      }\n\n      .hud-score { color: var(--neon-cyan); }\n      .hud-level { color: var(--neon-yellow); }\n      .hud-lives { color: var(--neon-pink); }\n      .hud-high { color: var(--neon-green); }\n\n      /* Overlays */\n      .overlay {\n        position: absolute;\n        top: 0; left: 0; right: 0; bottom: 0;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        justify-content: center;\n        z-index: 20;\n        background: rgba(5, 5, 15, 0.75);\n        backdrop-filter: blur(8px);\n        -webkit-backdrop-filter: blur(8px);\n        transition: opacity 0.3s ease;\n      }\n\n      .overlay.hidden {\n        opacity: 0;\n        pointer-events: none;\n      }\n\n      .overlay h1 {\n        font-size: 52px;\n        font-weight: 800;\n        letter-spacing: 4px;\n        text-transform: uppercase;\n        margin-bottom: 8px;\n        background: linear-gradient(135deg, var(--neon-cyan), var(--neon-pink));\n        -webkit-background-clip: text;\n        background-clip: text;\n        -webkit-text-fill-color: transparent;\n        filter: drop-shadow(0 0 30px rgba(0, 240, 255, 0.3));\n        animation: titlePulse 2s ease-in-out infinite;\n      }\n\n      @keyframes titlePulse {\n        0%, 100% { filter: drop-shadow(0 0 30px rgba(0, 240, 255, 0.3)); }\n        50% { filter: drop-shadow(0 0 50px rgba(255, 46, 147, 0.4)); }\n      }\n\n      .overlay h2 {\n        font-size: 32px;\n        font-weight: 700;\n        letter-spacing: 3px;\n        text-transform: uppercase;\n        margin-bottom: 8px;\n      }\n\n      .overlay h2.win { color: var(--neon-green); text-shadow: 0 0 20px var(--neon-green); }\n      .overlay h2.lose { color: var(--neon-pink); text-shadow: 0 0 20px var(--neon-pink); }\n\n      .overlay .subtitle {\n        font-size: 15px;\n        color: rgba(255, 255, 255, 0.5);\n        letter-spacing: 2px;\n        margin-bottom: 36px;\n        text-transform: uppercase;\n      }\n\n      .overlay .stats {\n        display: flex;\n        gap: 40px;\n        margin-bottom: 36px;\n      }\n\n      .overlay .stat {\n        text-align: center;\n      }\n\n      .overlay .stat-label {\n        font-size: 11px;\n        color: rgba(255, 255, 255, 0.4);\n        letter-spacing: 2px;\n        text-transform: uppercase;\n        margin-bottom: 4px;\n      }\n\n      .overlay .stat-value {\n        font-size: 28px;\n        font-weight: 700;\n        color: var(--neon-cyan);\n        text-shadow: 0 0 12px var(--neon-cyan);\n      }\n\n      .overlay .stat-value.new {\n        color: var(--neon-yellow);\n        text-shadow: 0 0 12px var(--neon-yellow);\n      }\n\n      .btn {\n        padding: 14px 40px;\n        font-size: 16px;\n        font-weight: 700;\n        letter-spacing: 3px;\n        text-transform: uppercase;\n        border: 2px solid var(--neon-cyan);\n        border-radius: 50px;\n        background: transparent;\n        color: var(--neon-cyan);\n        cursor: pointer;\n        transition: all 0.25s ease;\n        text-shadow: 0 0 8px var(--neon-cyan);\n        box-shadow: 0 0 20px rgba(0, 240, 255, 0.2), inset 0 0 20px rgba(0, 240, 255, 0.05);\n        margin-bottom: 10px;\n      }\n\n      .btn:hover {\n        background: rgba(0, 240, 255, 0.1);\n        box-shadow: 0 0 30px rgba(0, 240, 255, 0.4), inset 0 0 30px rgba(0, 240, 255, 0.1);\n        transform: scale(1.05);\n      }\n\n      .btn:active { transform: scale(0.98); }\n\n      .btn.pink {\n        border-color: var(--neon-pink);\n        color: var(--neon-pink);\n        text-shadow: 0 0 8px var(--neon-pink);\n        box-shadow: 0 0 20px rgba(255, 46, 147, 0.2), inset 0 0 20px rgba(255, 46, 147, 0.05);\n      }\n      .btn.pink:hover {\n        background: rgba(255, 46, 147, 0.1);\n        box-shadow: 0 0 30px rgba(255, 46, 147, 0.4), inset 0 0 30px rgba(255, 46, 147, 0.1);\n      }\n\n      .instructions {\n        margin-top: 20px;\n        font-size: 13px;\n        color: rgba(255, 255, 255, 0.35);\n        letter-spacing: 1px;\n        text-align: center;\n        line-height: 1.8;\n      }\n\n      .instructions kbd {\n        display: inline-block;\n        padding: 2px 8px;\n        border: 1px solid rgba(255, 255, 255, 0.2);\n        border-radius: 4px;\n        font-size: 12px;\n        font-family: monospace;\n        background: rgba(255, 255, 255, 0.05);\n        color: rgba(255, 255, 255, 0.6);\n        margin: 0 2px;\n      }\n\n      .new-badge {\n        display: inline-block;\n        font-size: 11px;\n        color: var(--neon-yellow);\n        text-shadow: 0 0 8px var(--neon-yellow);\n        margin-left: 8px;\n        animation: blink 1s ease-in-out infinite;\n        letter-spacing: 2px;\n      }\n\n      @keyframes blink {\n        0%, 100% { opacity: 1; }\n        50% { opacity: 0.3; }\n      }\n\n      /* Mobile controls */\n      #touch-controls {\n        position: absolute;\n        bottom: 20px;\n        left: 50%;\n        transform: translateX(-50%);\n        display: none;\n        gap: 16px;\n        z-index: 15;\n      }\n\n      .touch-btn {\n        width: 64px;\n        height: 64px;\n        border-radius: 50%;\n        border: 2px solid rgba(0, 240, 255, 0.4);\n        background: rgba(0, 240, 255, 0.08);\n        color: var(--neon-cyan);\n        font-size: 28px;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        cursor: pointer;\n        touch-action: none;\n        -webkit-tap-highlight-color: transparent;\n      }\n\n      .touch-btn:active {\n        background: rgba(0, 240, 255, 0.2);\n        box-shadow: 0 0 20px rgba(0, 240, 255, 0.3);\n      }\n\n      @media (max-width: 768px) {\n        #touch-controls { display: flex; }\n        .overlay h1 { font-size: 36px; }\n        .overlay h2 { font-size: 24px; }\n        #hud { gap: 16px; font-size: 12px; }\n        .hud-value { font-size: 16px; }\n      }\n    </style>\n    <meta property=\"og:image\" content=\"https://bolt.new/static/og_default.png\">\n    <meta name=\"twitter:card\" content=\"summary_large_image\">\n    <meta name=\"twitter:image\" content=\"https://bolt.new/static/og_default.png\">\n</head>\n  <body>\n    <div id=\"game-container\">\n      <canvas id=\"game\"></canvas>\n\n      <div id=\"hud\">\n        <div class=\"hud-item\">\n          <span class=\"hud-label\">Score</span>\n          <span class=\"hud-value hud-score\" id=\"hud-score\">0</span>\n        </div>\n        <div class=\"hud-item\">\n          <span class=\"hud-label\">Level</span>\n          <span class=\"hud-value hud-level\" id=\"hud-level\">1</span>\n        </div>\n        <div class=\"hud-item\">\n          <span class=\"hud-label\">Lives</span>\n          <span class=\"hud-value hud-lives\" id=\"hud-lives\">3</span>\n        </div>\n        <div class=\"hud-item\">\n          <span class=\"hud-label\">Best</span>\n          <span class=\"hud-value hud-high\" id=\"hud-high\">0</span>\n        </div>\n      </div>\n\n      <!-- Menu overlay -->\n      <div class=\"overlay\" id=\"overlay-menu\">\n        <h1>Neon Breakout</h1>\n        <p class=\"subtitle\">Smash every brick. Clear every level.</p>\n        <button class=\"btn\" id=\"btn-start\">Start Game</button>\n        <div class=\"instructions\">\n          <kbd>←</kbd> <kbd>→</kbd> or <kbd>A</kbd> <kbd>D</kbd> — Move paddle<br>\n          <kbd>Space</kbd> — Launch ball / Pause<br>\n          Mouse or touch also supported\n        </div>\n      </div>\n\n      <!-- Pause overlay -->\n      <div class=\"overlay hidden\" id=\"overlay-pause\">\n        <h2>Paused</h2>\n        <p class=\"subtitle\">Take a breath</p>\n        <button class=\"btn\" id=\"btn-resume\">Resume</button>\n        <button class=\"btn pink\" id=\"btn-quit\">Quit to Menu</button>\n      </div>\n\n      <!-- Game over overlay -->\n      <div class=\"overlay hidden\" id=\"overlay-gameover\">\n        <h2 class=\"lose\">Game Over</h2>\n        <p class=\"subtitle\">The bricks won this round</p>\n        <div class=\"stats\">\n          <div class=\"stat\">\n            <div class=\"stat-label\">Score</div>\n            <div class=\"stat-value\" id=\"go-score\">0</div>\n          </div>\n          <div class=\"stat\">\n            <div class=\"stat-label\">Level</div>\n            <div class=\"stat-value\" id=\"go-level\">1</div>\n          </div>\n          <div class=\"stat\">\n            <div class=\"stat-label\">Best</div>\n            <div class=\"stat-value\" id=\"go-high\">0</div>\n          </div>\n        </div>\n        <button class=\"btn\" id=\"btn-retry\">Try Again</button>\n        <button class=\"btn pink\" id=\"btn-menu\">Main Menu</button>\n      </div>\n\n      <!-- Level complete overlay -->\n      <div class=\"overlay hidden\" id=\"overlay-levelcomplete\">\n        <h2 class=\"win\">Level Complete!</h2>\n        <p class=\"subtitle\" id=\"lc-subtitle\">Get ready for the next level</p>\n        <div class=\"stats\">\n          <div class=\"stat\">\n            <div class=\"stat-label\">Score</div>\n            <div class=\"stat-value\" id=\"lc-score\">0</div>\n          </div>\n        </div>\n        <button class=\"btn\" id=\"btn-next\">Next Level</button>\n      </div>\n\n      <!-- Victory overlay -->\n      <div class=\"overlay hidden\" id=\"overlay-victory\">\n        <h1>You Win!</h1>\n        <p class=\"subtitle\">All levels conquered</p>\n        <div class=\"stats\">\n          <div class=\"stat\">\n            <div class=\"stat-label\">Final Score</div>\n            <div class=\"stat-value\" id=\"v-score\">0</div>\n          </div>\n          <div class=\"stat\">\n            <div class=\"stat-label\">Best</div>\n            <div class=\"stat-value\" id=\"v-high\">0</div>\n          </div>\n        </div>\n        <button class=\"btn\" id=\"btn-victory-retry\">Play Again</button>\n      </div>\n\n      <div id=\"touch-controls\">\n        <div class=\"touch-btn\" id=\"touch-left\">◀</div>\n        <div class=\"touch-btn\" id=\"touch-right\">▶</div>\n      </div>\n    </div>\n\n    <script>\n    (function () {\n      'use strict';\n\n      // ── Canvas setup ──────────────────────────────────────\n      const canvas = document.getElementById('game');\n      const ctx = canvas.getContext('2d');\n      const container = document.getElementById('game-container');\n\n      let CW = 0, CH = 0; // canvas logical size\n\n      function resize() {\n        const margin = window.innerWidth < 768 ? 20 : 40;\n        const maxW = Math.min(window.innerWidth - margin, 720);\n        const maxH = Math.min(window.innerHeight - (window.innerWidth < 768 ? 160 : 120), 900);\n        const ratio = 3 / 4; // width / height\n        let w, h;\n        if (maxW / maxH < ratio) {\n          w = maxW;\n          h = maxW / ratio;\n        } else {\n          h = maxH;\n          w = maxH * ratio;\n        }\n        CW = Math.floor(w);\n        CH = Math.floor(h);\n        canvas.width = CW * devicePixelRatio;\n        canvas.height = CH * devicePixelRatio;\n        canvas.style.width = CW + 'px';\n        canvas.style.height = CH + 'px';\n        ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);\n        if (game.state === 'menu') {\n          buildLevel(1);\n        }\n      }\n\n      // ── Audio (Web Audio API, no files) ───────────────────\n      let audioCtx = null;\n      function initAudio() {\n        if (!audioCtx) {\n          try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) {}\n        }\n        if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();\n      }\n\n      function beep(freq, dur, type, vol) {\n        if (!audioCtx) return;\n        const osc = audioCtx.createOscillator();\n        const gain = audioCtx.createGain();\n        osc.type = type || 'sine';\n        osc.frequency.setValueAtTime(freq, audioCtx.currentTime);\n        gain.gain.setValueAtTime(0, audioCtx.currentTime);\n        gain.gain.linearRampToValueAtTime(vol || 0.15, audioCtx.currentTime + 0.005);\n        gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);\n        osc.connect(gain);\n        gain.connect(audioCtx.destination);\n        osc.start();\n        osc.stop(audioCtx.currentTime + dur);\n      }\n\n      const SFX = {\n        hit:    () => beep(440, 0.08, 'square', 0.12),\n        paddle: () => beep(260, 0.06, 'triangle', 0.15),\n        brick:  () => { beep(520, 0.06, 'square', 0.12); beep(780, 0.04, 'sine', 0.08); },\n        power:  () => { beep(660, 0.1, 'sine', 0.15); setTimeout(() => beep(990, 0.08, 'sine', 0.12), 60); },\n        lose:   () => { beep(200, 0.15, 'sawtooth', 0.18); setTimeout(() => beep(120, 0.25, 'sawtooth', 0.15), 100); },\n        win:    () => { [523, 659, 784, 1047].forEach((f, i) => setTimeout(() => beep(f, 0.15, 'sine', 0.15), i * 80)); },\n        level:  () => { [392, 523, 659].forEach((f, i) => setTimeout(() => beep(f, 0.12, 'sine', 0.14), i * 70)); },\n      };\n\n      // ── Game state ────────────────────────────────────────\n      const game = {\n        state: 'menu',        // menu | playing | paused | gameover | levelcomplete | victory\n        score: 0,\n        highScore: parseInt(localStorage.getItem('neonBreakoutHigh') || '0', 10),\n        level: 1,\n        maxLevel: 8,\n        lives: 3,\n        shake: 0,\n        flashAlpha: 0,\n        ballLaunched: false,\n      };\n\n      // ── Entities ──────────────────────────────────────────\n      let paddle = { x: 0, y: 0, w: 110, h: 14, speed: 8, baseW: 110, wideTimer: 0 };\n      let balls = [];\n      let bricks = [];\n      let particles = [];\n      let powerups = [];\n      let floatingTexts = [];\n      let keys = { left: false, right: false };\n\n      const BRICK_COLS = 10;\n\n      const LEVEL_LAYOUTS = [\n        // Level 1 — gentle rows\n        [\n          '..xxxxxxx..',\n          '.xxxxxxxxx.',\n          'xxxxxxxxxxx',\n          '.xxxxxxxxx.',\n          '..xxxxxxx..',\n        ],\n        // Level 2 — pyramid\n        [\n          '....x....',\n          '...xxx...',\n          '..xxxxx..',\n          '.xxxxxxx.',\n          'xxxxxxxxx',\n        ],\n        // Level 3 — checkerboard\n        [\n          'x.x.x.x.x.',\n          '.x.x.x.x.x',\n          'x.x.x.x.x.',\n          '.x.x.x.x.x',\n          'x.x.x.x.x.',\n        ],\n        // Level 4 — diamond\n        [\n          '....x....',\n          '...xxx...',\n          '..xxxxx..',\n          '.xxxxxxx.',\n          '..xxxxx..',\n          '...xxx...',\n          '....x....',\n        ],\n        // Level 5 — walls\n        [\n          'x.......x',\n          'xx.....xx',\n          'x.x...x.x',\n          'x..x.x..x',\n          'x...x...x',\n          'x..x.x..x',\n          'x.x...x.x',\n          'xx.....xx',\n          'x.......x',\n        ],\n        // Level 6 — heart\n        [\n          '.xx...xx.',\n          'xxxxx.xxx',\n          'xxxxxxxxx',\n          '.xxxxxxx.',\n          '..xxxxx..',\n          '...xxx...',\n          '....x....',\n        ],\n        // Level 7 — fortress\n        [\n          'xxxxxxxxx',\n          'x.......x',\n          'x.xxxxx.x',\n          'x.x...x.x',\n          'x.x.x.x.x',\n          'x.x...x.x',\n          'x.xxxxx.x',\n          'x.......x',\n          'xxxxxxxxx',\n        ],\n        // Level 8 — final challenge\n        [\n          'xxxxxxxxx',\n          'xxxxxxxxx',\n          'xx.x.x.xx',\n          'x..x.x..x',\n          'x.x.x.x.x',\n          'x..x.x..x',\n          'xx.x.x.xx',\n          'xxxxxxxxx',\n          'xxxxxxxxx',\n        ],\n      ];\n\n      function getLevelLayout(level) {\n        return LEVEL_LAYOUTS[Math.min(level - 1, LEVEL_LAYOUTS.length - 1)];\n      }\n\n      function brickColor(row) {\n        const colors = [\n          { fill: '#ff2e93', glow: 'rgba(255, 46, 147, 0.6)' },\n          { fill: '#ff6b00', glow: 'rgba(255, 107, 0, 0.6)' },\n          { fill: '#ffe600', glow: 'rgba(255, 230, 0, 0.6)' },\n          { fill: '#39ff14', glow: 'rgba(57, 255, 20, 0.6)' },\n          { fill: '#00f0ff', glow: 'rgba(0, 240, 255, 0.6)' },\n          { fill: '#b388ff', glow: 'rgba(179, 136, 255, 0.6)' },\n          { fill: '#ff2e93', glow: 'rgba(255, 46, 147, 0.6)' },\n          { fill: '#ff6b00', glow: 'rgba(255, 107, 0, 0.6)' },\n          { fill: '#ffe600', glow: 'rgba(255, 230, 0, 0.6)' },\n        ];\n        return colors[row % colors.length];\n      }\n\n      function buildLevel(level) {\n        const layout = getLevelLayout(level);\n        const rows = layout.length;\n        const cols = Math.max(...layout.map(r => r.length));\n        const topPad = 70;\n        const sidePad = 20;\n        const brickW = (CW - sidePad * 2) / cols;\n        const brickH = 22;\n        const gap = 3;\n\n        bricks = [];\n        for (let r = 0; r < rows; r++) {\n          for (let c = 0; c < layout[r].length; c++) {\n            if (layout[r][c] === 'x') {\n              bricks.push({\n                x: sidePad + c * brickW + gap / 2,\n                y: topPad + r * (brickH + gap),\n                w: brickW - gap,\n                h: brickH,\n                color: brickColor(r),\n                hp: 1,\n                hit: false,\n                hitAnim: 0,\n              });\n            }\n          }\n        }\n\n        // Reset paddle\n        paddle.w = paddle.baseW;\n        paddle.x = CW / 2 - paddle.w / 2;\n        paddle.y = CH - 40;\n        paddle.wideTimer = 0;\n\n        // Reset ball\n        balls = [createBall(true)];\n        game.ballLaunched = false;\n        powerups = [];\n        particles = [];\n        floatingTexts = [];\n      }\n\n      function createBall(onPaddle) {\n        return {\n          x: paddle.x + paddle.w / 2,\n          y: paddle.y - 10,\n          vx: 0,\n          vy: 0,\n          r: 8,\n          baseSpeed: 5.5 + (game.level - 1) * 0.4,\n          onPaddle: onPaddle !== false,\n          trail: [],\n        };\n      }\n\n      // ── Power-ups ─────────────────────────────────────────\n      const POWERUP_TYPES = ['multi', 'wide', 'slow', 'life'];\n      const POWERUP_COLORS = {\n        multi: '#00f0ff',\n        wide:  '#39ff14',\n        slow:  '#b388ff',\n        life:  '#ff2e93',\n      };\n      const POWERUP_LABELS = {\n        multi: '3x',\n        wide:  'W',\n        slow:  'S',\n        life:  '+1',\n      };\n\n      function maybeDropPowerup(x, y) {\n        if (Math.random() < 0.12) {\n          const type = POWERUP_TYPES[Math.floor(Math.random() * POWERUP_TYPES.length)];\n          powerups.push({\n            x, y,\n            w: 30, h: 16,\n            vy: 2.5,\n            type,\n            color: POWERUP_COLORS[type],\n            label: POWERUP_LABELS[type],\n            wobble: 0,\n          });\n        }\n      }\n\n      function applyPowerup(type) {\n        SFX.power();\n        const msg = { multi: 'Multi-Ball!', wide: 'Wide Paddle!', slow: 'Slow Motion!', life: 'Extra Life!' };\n        floatingTexts.push({ text: msg[type], x: CW / 2, y: CH / 2, alpha: 1, vy: -1.5, color: POWERUP_COLORS[type], size: 24 });\n\n        if (type === 'multi') {\n          const existing = balls.filter(b => !b.onPaddle);\n          if (existing.length === 0) {\n            const b = balls[0];\n            if (b && b.onPaddle) launchBall(b);\n            const cur = balls[0];\n            if (cur) {\n              for (let i = 0; i < 2; i++) {\n                const nb = createBall(false);\n                nb.x = cur.x; nb.y = cur.y;\n                const angle = (-60 + i * 120) * Math.PI / 180;\n                nb.vx = Math.sin(angle) * cur.baseSpeed;\n                nb.vy = -Math.abs(Math.cos(angle) * cur.baseSpeed);\n                balls.push(nb);\n              }\n            }\n          } else {\n            const src = existing[0];\n            for (let i = 0; i < 2; i++) {\n              const nb = createBall(false);\n              nb.x = src.x; nb.y = src.y;\n              const angle = (-60 + i * 120) * Math.PI / 180;\n              nb.vx = Math.sin(angle) * src.baseSpeed;\n              nb.vy = -Math.abs(Math.cos(angle) * src.baseSpeed);\n              nb.vx += src.vx * 0.3;\n              nb.vy += src.vy * 0.3;\n              balls.push(nb);\n            }\n          }\n        } else if (type === 'wide') {\n          paddle.w = paddle.baseW * 1.6;\n          paddle.wideTimer = 600; // ~10 seconds at 60fps\n        } else if (type === 'slow') {\n          balls.forEach(b => {\n            if (!b.onPaddle) {\n              b.vx *= 0.6;\n              b.vy *= 0.6;\n              b.slowTimer = 360;\n            }\n          });\n        } else if (type === 'life') {\n          game.lives++;\n          updateHUD();\n        }\n      }\n\n      // ── Particles ─────────────────────────────────────────\n      function spawnExplosion(x, y, color, count) {\n        for (let i = 0; i < (count || 14); i++) {\n          const angle = Math.random() * Math.PI * 2;\n          const speed = 1 + Math.random() * 4;\n          particles.push({\n            x, y,\n            vx: Math.cos(angle) * speed,\n            vy: Math.sin(angle) * speed,\n            life: 1,\n            decay: 0.02 + Math.random() * 0.02,\n            size: 2 + Math.random() * 3,\n            color,\n          });\n        }\n      }\n\n      function spawnSparks(x, y, color, count) {\n        for (let i = 0; i < (count || 6); i++) {\n          const angle = -Math.PI / 2 + (Math.random() - 0.5) * Math.PI * 0.8;\n          const speed = 1 + Math.random() * 2.5;\n          particles.push({\n            x, y,\n            vx: Math.cos(angle) * speed,\n            vy: Math.sin(angle) * speed,\n            life: 1,\n            decay: 0.04 + Math.random() * 0.03,\n            size: 1.5 + Math.random() * 2,\n            color,\n          });\n        }\n      }\n\n      // ── Input ─────────────────────────────────────────────\n      document.addEventListener('keydown', function (e) {\n        if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') keys.left = true;\n        if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') keys.right = true;\n        if (e.key === ' ') {\n          e.preventDefault();\n          initAudio();\n          if (game.state === 'menu') { startGame(); return; }\n          if (game.state === 'playing') {\n            if (!game.ballLaunched) {\n              balls.forEach(b => { if (b.onPaddle) launchBall(b); });\n              game.ballLaunched = true;\n            } else {\n              pauseGame();\n            }\n          } else if (game.state === 'paused') {\n            resumeGame();\n          }\n        }\n        if (e.key === 'Escape') {\n          if (game.state === 'playing') pauseGame();\n          else if (game.state === 'paused') resumeGame();\n        }\n      });\n\n      document.addEventListener('keyup', function (e) {\n        if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') keys.left = false;\n        if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') keys.right = false;\n      });\n\n      // Mouse\n      canvas.addEventListener('mousemove', function (e) {\n        if (game.state !== 'playing') return;\n        const rect = canvas.getBoundingClientRect();\n        const mx = e.clientX - rect.left;\n        paddle.x = clamp(mx - paddle.w / 2, 0, CW - paddle.w);\n        if (!game.ballLaunched) {\n          balls.forEach(b => { if (b.onPaddle) b.x = paddle.x + paddle.w / 2; });\n        }\n      });\n\n      canvas.addEventListener('click', function () {\n        initAudio();\n        if (game.state === 'playing' && !game.ballLaunched) {\n          balls.forEach(b => { if (b.onPaddle) launchBall(b); });\n          game.ballLaunched = true;\n        }\n      });\n\n      // Touch\n      canvas.addEventListener('touchmove', function (e) {\n        if (game.state !== 'playing') return;\n        e.preventDefault();\n        const rect = canvas.getBoundingClientRect();\n        const tx = e.touches[0].clientX - rect.left;\n        paddle.x = clamp(tx - paddle.w / 2, 0, CW - paddle.w);\n        if (!game.ballLaunched) {\n          balls.forEach(b => { if (b.onPaddle) b.x = paddle.x + paddle.w / 2; });\n        }\n      }, { passive: false });\n\n      canvas.addEventListener('touchstart', function (e) {\n        initAudio();\n        if (game.state === 'playing' && !game.ballLaunched) {\n          balls.forEach(b => { if (b.onPaddle) launchBall(b); });\n          game.ballLaunched = true;\n        }\n      }, { passive: true });\n\n      // Touch buttons\n      const touchLeft = document.getElementById('touch-left');\n      const touchRight = document.getElementById('touch-right');\n      function bindTouch(el, dir) {\n        const press = (e) => { e.preventDefault(); keys[dir] = true; };\n        const release = (e) => { e.preventDefault(); keys[dir] = false; };\n        el.addEventListener('touchstart', press, { passive: false });\n        el.addEventListener('touchend', release, { passive: false });\n        el.addEventListener('touchcancel', release, { passive: false });\n        el.addEventListener('mousedown', press);\n        el.addEventListener('mouseup', release);\n        el.addEventListener('mouseleave', release);\n      }\n      bindTouch(touchLeft, 'left');\n      bindTouch(touchRight, 'right');\n\n      // ── UI bindings ───────────────────────────────────────\n      const overlays = {\n        menu: document.getElementById('overlay-menu'),\n        pause: document.getElementById('overlay-pause'),\n        gameover: document.getElementById('overlay-gameover'),\n        levelcomplete: document.getElementById('overlay-levelcomplete'),\n        victory: document.getElementById('overlay-victory'),\n      };\n\n      function showOverlay(name) {\n        Object.values(overlays).forEach(o => o.classList.add('hidden'));\n        if (name) overlays[name].classList.remove('hidden');\n      }\n\n      document.getElementById('btn-start').addEventListener('click', () => { initAudio(); startGame(); });\n      document.getElementById('btn-resume').addEventListener('click', resumeGame);\n      document.getElementById('btn-quit').addEventListener('click', quitToMenu);\n      document.getElementById('btn-retry').addEventListener('click', () => { initAudio(); startGame(); });\n      document.getElementById('btn-menu').addEventListener('click', quitToMenu);\n      document.getElementById('btn-next').addEventListener('click', nextLevel);\n      document.getElementById('btn-victory-retry').addEventListener('click', () => { initAudio(); startGame(); });\n\n      function startGame() {\n        game.score = 0;\n        game.level = 1;\n        game.lives = 3;\n        game.state = 'playing';\n        buildLevel(1);\n        updateHUD();\n        showOverlay(null);\n      }\n\n      function pauseGame() {\n        if (game.state !== 'playing') return;\n        game.state = 'paused';\n        showOverlay('pause');\n      }\n\n      function resumeGame() {\n        if (game.state !== 'paused') return;\n        game.state = 'playing';\n        showOverlay(null);\n      }\n\n      function quitToMenu() {\n        game.state = 'menu';\n        buildLevel(1);\n        updateHUD();\n        showOverlay('menu');\n      }\n\n      function nextLevel() {\n        game.level++;\n        if (game.level > game.maxLevel) {\n          game.state = 'victory';\n          checkHighScore();\n          document.getElementById('v-score').textContent = game.score;\n          document.getElementById('v-high').textContent = game.highScore;\n          showOverlay('victory');\n          SFX.win();\n          return;\n        }\n        game.state = 'playing';\n        buildLevel(game.level);\n        updateHUD();\n        showOverlay(null);\n      }\n\n      function gameOver() {\n        game.state = 'gameover';\n        checkHighScore();\n        document.getElementById('go-score').textContent = game.score;\n        document.getElementById('go-level').textContent = game.level;\n        document.getElementById('go-high').textContent = game.highScore;\n        showOverlay('gameover');\n        SFX.lose();\n      }\n\n      function levelComplete() {\n        game.state = 'levelcomplete';\n        document.getElementById('lc-score').textContent = game.score;\n        const isLast = game.level >= game.maxLevel;\n        document.getElementById('btn-next').textContent = isLast ? 'Finish' : 'Next Level';\n        showOverlay('levelcomplete');\n        SFX.level();\n      }\n\n      function checkHighScore() {\n        if (game.score > game.highScore) {\n          game.highScore = game.score;\n          localStorage.setItem('neonBreakoutHigh', String(game.highScore));\n        }\n      }\n\n      function updateHUD() {\n        document.getElementById('hud-score').textContent = game.score;\n        document.getElementById('hud-level').textContent = game.level;\n        document.getElementById('hud-lives').textContent = game.lives;\n        document.getElementById('hud-high').textContent = game.highScore;\n      }\n\n      // ── Helpers ───────────────────────────────────────────\n      function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }\n\n      function launchBall(b) {\n        b.onPaddle = false;\n        const angle = (-45 + Math.random() * 30 - 15) * Math.PI / 180;\n        b.vx = Math.sin(angle) * b.baseSpeed;\n        b.vy = -Math.abs(Math.cos(angle) * b.baseSpeed);\n      }\n\n      function ballSpeed(b) {\n        return Math.sqrt(b.vx * b.vx + b.vy * b.vy);\n      }\n\n      function normalizeBallSpeed(b) {\n        const s = ballSpeed(b);\n        if (s > 0) {\n          const target = b.baseSpeed * (b.slowTimer > 0 ? 0.6 : 1);\n          b.vx = (b.vx / s) * target;\n          b.vy = (b.vy / s) * target;\n        }\n      }\n\n      // ── Collision ─────────────────────────────────────────\n      function ballPaddleCollision(b) {\n        if (b.y + b.r < paddle.y) return false;\n        if (b.y - b.r > paddle.y + paddle.h) return false;\n        if (b.x + b.r < paddle.x) return false;\n        if (b.x - b.r > paddle.x + paddle.w) return false;\n\n        // Reflect with angle based on hit position\n        const hitPos = (b.x - paddle.x) / paddle.w; // 0..1\n        const angle = (hitPos - 0.5) * Math.PI * 0.7; // -63°..63°\n        const speed = ballSpeed(b);\n        b.vx = Math.sin(angle) * speed;\n        b.vy = -Math.abs(Math.cos(angle) * speed);\n        b.y = paddle.y - b.r - 1;\n\n        spawnSparks(b.x, paddle.y, '#00f0ff', 5);\n        SFX.paddle();\n        return true;\n      }\n\n      function ballBrickCollision(b) {\n        for (let i = 0; i < bricks.length; i++) {\n          const br = bricks[i];\n          if (br.hit) continue;\n          if (b.x + b.r < br.x) continue;\n          if (b.x - b.r > br.x + br.w) continue;\n          if (b.y + b.r < br.y) continue;\n          if (b.y - b.r > br.y + br.h) continue;\n\n          // Determine bounce direction\n          const prevX = b.x - b.vx;\n          const prevY = b.y - b.vy;\n          const fromLeft = prevX + b.r <= br.x;\n          const fromRight = prevX - b.r >= br.x + br.w;\n          const fromTop = prevY + b.r <= br.y;\n          const fromBottom = prevY - b.r >= br.y + br.h;\n\n          if (fromLeft || fromRight) {\n            b.vx = -b.vx;\n          } else if (fromTop || fromBottom) {\n            b.vy = -b.vy;\n          } else {\n            b.vy = -b.vy;\n          }\n\n          br.hit = true;\n          br.hitAnim = 1;\n          game.score += 10 * game.level;\n          spawnExplosion(br.x + br.w / 2, br.y + br.h / 2, br.color.fill, 12);\n          maybeDropPowerup(br.x + br.w / 2, br.y + br.h / 2);\n          SFX.brick();\n          updateHUD();\n          game.shake = Math.min(game.shake + 3, 8);\n\n          // Remove after animation\n          bricks.splice(i, 1);\n          return true;\n        }\n        return false;\n      }\n\n      // ── Update ────────────────────────────────────────────\n      function update() {\n        if (game.state !== 'playing') return;\n\n        // Paddle keyboard movement\n        if (keys.left) paddle.x -= paddle.speed;\n        if (keys.right) paddle.x += paddle.speed;\n        paddle.x = clamp(paddle.x, 0, CW - paddle.w);\n\n        // Wide paddle timer\n        if (paddle.wideTimer > 0) {\n          paddle.wideTimer--;\n          if (paddle.wideTimer === 0) {\n            paddle.w = paddle.baseW;\n          }\n        }\n\n        // Update balls\n        for (let bi = balls.length - 1; bi >= 0; bi--) {\n          const b = balls[bi];\n\n          if (b.onPaddle) {\n            b.x = paddle.x + paddle.w / 2;\n            b.y = paddle.y - b.r - 2;\n            continue;\n          }\n\n          // Trail\n          b.trail.push({ x: b.x, y: b.y });\n          if (b.trail.length > 8) b.trail.shift();\n\n          // Slow timer\n          if (b.slowTimer > 0) {\n            b.slowTimer--;\n            if (b.slowTimer === 0) normalizeBallSpeed(b);\n          }\n\n          b.x += b.vx;\n          b.y += b.vy;\n\n          // Wall collisions\n          if (b.x - b.r < 0) { b.x = b.r; b.vx = -b.vx; SFX.hit(); spawnSparks(b.x, b.y, '#00f0ff', 3); }\n          if (b.x + b.r > CW) { b.x = CW - b.r; b.vx = -b.vx; SFX.hit(); spawnSparks(b.x, b.y, '#00f0ff', 3); }\n          if (b.y - b.r < 0) { b.y = b.r; b.vy = -b.vy; SFX.hit(); spawnSparks(b.x, b.y, '#00f0ff', 3); }\n\n          // Bottom — lose ball\n          if (b.y - b.r > CH) {\n            balls.splice(bi, 1);\n            spawnExplosion(b.x, CH - 5, '#ff2e93', 16);\n            if (balls.length === 0) {\n              game.lives--;\n              updateHUD();\n              SFX.lose();\n              game.shake = 12;\n              game.flashAlpha = 0.4;\n              if (game.lives <= 0) {\n                gameOver();\n              } else {\n                balls = [createBall(true)];\n                game.ballLaunched = false;\n              }\n            }\n            continue;\n          }\n\n          ballPaddleCollision(b);\n          ballBrickCollision(b);\n        }\n\n        // Check level complete\n        if (bricks.length === 0 && game.state === 'playing') {\n          levelComplete();\n          return;\n        }\n\n        // Update powerups\n        for (let i = powerups.length - 1; i >= 0; i--) {\n          const p = powerups[i];\n          p.y += p.vy;\n          p.wobble += 0.08;\n          p.x += Math.sin(p.wobble) * 0.5;\n\n          // Paddle catch\n          if (p.y + p.h >= paddle.y && p.y <= paddle.y + paddle.h &&\n              p.x + p.w >= paddle.x && p.x <= paddle.x + paddle.w) {\n            applyPowerup(p.type);\n            powerups.splice(i, 1);\n            continue;\n          }\n          if (p.y > CH) powerups.splice(i, 1);\n        }\n\n        // Update particles\n        for (let i = particles.length - 1; i >= 0; i--) {\n          const p = particles[i];\n          p.x += p.vx;\n          p.y += p.vy;\n          p.vy += 0.08; // gravity\n          p.life -= p.decay;\n          if (p.life <= 0) particles.splice(i, 1);\n        }\n\n        // Update floating texts\n        for (let i = floatingTexts.length - 1; i >= 0; i--) {\n          const t = floatingTexts[i];\n          t.y += t.vy;\n          t.alpha -= 0.012;\n          if (t.alpha <= 0) floatingTexts.splice(i, 1);\n        }\n\n        // Screen shake decay\n        if (game.shake > 0) game.shake *= 0.85;\n        if (game.flashAlpha > 0) game.flashAlpha *= 0.9;\n      }\n\n      // ── Render ────────────────────────────────────────────\n      function render() {\n        ctx.clearRect(0, 0, CW, CH);\n\n        // Screen shake\n        let sx = 0, sy = 0;\n        if (game.shake > 0.5) {\n          sx = (Math.random() - 0.5) * game.shake;\n          sy = (Math.random() - 0.5) * game.shake;\n        }\n        ctx.save();\n        ctx.translate(sx, sy);\n\n        // Background grid\n        drawBackgroundGrid();\n\n        // Bricks\n        for (const br of bricks) {\n          drawBrick(br);\n        }\n\n        // Powerups\n        for (const p of powerups) {\n          drawPowerup(p);\n        }\n\n        // Particles\n        for (const p of particles) {\n          ctx.globalAlpha = p.life;\n          ctx.fillStyle = p.color;\n          ctx.shadowBlur = 10;\n          ctx.shadowColor = p.color;\n          ctx.beginPath();\n          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);\n          ctx.fill();\n        }\n        ctx.globalAlpha = 1;\n        ctx.shadowBlur = 0;\n\n        // Paddle\n        drawPaddle();\n\n        // Balls\n        for (const b of balls) {\n          drawBall(b);\n        }\n\n        // Floating texts\n        for (const t of floatingTexts) {\n          ctx.globalAlpha = t.alpha;\n          ctx.fillStyle = t.color;\n          ctx.font = 'bold ' + (t.size || 20) + 'px Segoe UI, sans-serif';\n          ctx.textAlign = 'center';\n          ctx.shadowBlur = 15;\n          ctx.shadowColor = t.color;\n          ctx.fillText(t.text, t.x, t.y);\n        }\n        ctx.globalAlpha = 1;\n        ctx.shadowBlur = 0;\n\n        // Launch hint\n        if (game.state === 'playing' && !game.ballLaunched && balls.length > 0 && balls[0].onPaddle) {\n          ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';\n          ctx.font = '13px Segoe UI, sans-serif';\n          ctx.textAlign = 'center';\n          ctx.fillText('Press SPACE or tap to launch', CW / 2, CH - 70);\n        }\n\n        ctx.restore();\n\n        // Flash overlay\n        if (game.flashAlpha > 0.01) {\n          ctx.fillStyle = 'rgba(255, 46, 147, ' + game.flashAlpha + ')';\n          ctx.fillRect(0, 0, CW, CH);\n        }\n      }\n\n      function drawBackgroundGrid() {\n        ctx.strokeStyle = 'rgba(0, 240, 255, 0.04)';\n        ctx.lineWidth = 1;\n        const gridSize = 30;\n        for (let x = 0; x < CW; x += gridSize) {\n          ctx.beginPath();\n          ctx.moveTo(x, 0);\n          ctx.lineTo(x, CH);\n          ctx.stroke();\n        }\n        for (let y = 0; y < CH; y += gridSize) {\n          ctx.beginPath();\n          ctx.moveTo(0, y);\n          ctx.lineTo(CW, y);\n          ctx.stroke();\n        }\n      }\n\n      function drawBrick(br) {\n        ctx.save();\n        ctx.shadowBlur = 12;\n        ctx.shadowColor = br.color.glow;\n        // Gradient fill\n        const grad = ctx.createLinearGradient(br.x, br.y, br.x, br.y + br.h);\n        grad.addColorStop(0, br.color.fill);\n        grad.addColorStop(1, shadeColor(br.color.fill, -25));\n        ctx.fillStyle = grad;\n        roundRect(ctx, br.x, br.y, br.w, br.h, 4);\n        ctx.fill();\n        // Top highlight\n        ctx.shadowBlur = 0;\n        ctx.fillStyle = 'rgba(255, 255, 255, 0.15)';\n        roundRect(ctx, br.x, br.y, br.w, br.h * 0.4, 4);\n        ctx.fill();\n        ctx.restore();\n      }\n\n      function drawPaddle() {\n        ctx.save();\n        ctx.shadowBlur = 20;\n        ctx.shadowColor = 'rgba(0, 240, 255, 0.5)';\n        const grad = ctx.createLinearGradient(paddle.x, paddle.y, paddle.x, paddle.y + paddle.h);\n        grad.addColorStop(0, '#00f0ff');\n        grad.addColorStop(0.5, '#0099cc');\n        grad.addColorStop(1, '#006688');\n        ctx.fillStyle = grad;\n        roundRect(ctx, paddle.x, paddle.y, paddle.w, paddle.h, 7);\n        ctx.fill();\n        // Highlight\n        ctx.shadowBlur = 0;\n        ctx.fillStyle = 'rgba(255, 255, 255, 0.25)';\n        roundRect(ctx, paddle.x + 2, paddle.y + 1, paddle.w - 4, paddle.h * 0.35, 5);\n        ctx.fill();\n        // Wide indicator\n        if (paddle.wideTimer > 0) {\n          const pct = paddle.wideTimer / 600;\n          ctx.fillStyle = 'rgba(57, 255, 20, ' + (0.4 + pct * 0.3) + ')';\n          ctx.fillRect(paddle.x, paddle.y + paddle.h + 3, paddle.w * pct, 2);\n        }\n        ctx.restore();\n      }\n\n      function drawBall(b) {\n        // Trail\n        for (let i = 0; i < b.trail.length; i++) {\n          const t = b.trail[i];\n          const alpha = (i / b.trail.length) * 0.4;\n          const size = b.r * (i / b.trail.length);\n          ctx.fillStyle = 'rgba(255, 255, 255, ' + alpha + ')';\n          ctx.beginPath();\n          ctx.arc(t.x, t.y, size, 0, Math.PI * 2);\n          ctx.fill();\n        }\n\n        ctx.save();\n        ctx.shadowBlur = 20;\n        ctx.shadowColor = b.slowTimer > 0 ? '#b388ff' : '#ffffff';\n        const grad = ctx.createRadialGradient(b.x - 2, b.y - 2, 1, b.x, b.y, b.r);\n        if (b.slowTimer > 0) {\n          grad.addColorStop(0, '#e0d0ff');\n          grad.addColorStop(1, '#b388ff');\n        } else {\n          grad.addColorStop(0, '#ffffff');\n          grad.addColorStop(1, '#a0e8ff');\n        }\n        ctx.fillStyle = grad;\n        ctx.beginPath();\n        ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.restore();\n      }\n\n      function drawPowerup(p) {\n        ctx.save();\n        ctx.shadowBlur = 15;\n        ctx.shadowColor = p.color;\n        const grad = ctx.createLinearGradient(p.x, p.y, p.x, p.y + p.h);\n        grad.addColorStop(0, p.color);\n        grad.addColorStop(1, shadeColor(p.color, -30));\n        ctx.fillStyle = grad;\n        roundRect(ctx, p.x - p.w / 2, p.y, p.w, p.h, 8);\n        ctx.fill();\n        ctx.shadowBlur = 0;\n        ctx.fillStyle = '#fff';\n        ctx.font = 'bold 10px Segoe UI, sans-serif';\n        ctx.textAlign = 'center';\n        ctx.textBaseline = 'middle';\n        ctx.fillText(p.label, p.x, p.y + p.h / 2);\n        ctx.restore();\n      }\n\n      function roundRect(ctx, x, y, w, h, r) {\n        r = Math.min(r, w / 2, h / 2);\n        ctx.beginPath();\n        ctx.moveTo(x + r, y);\n        ctx.arcTo(x + w, y, x + w, y + h, r);\n        ctx.arcTo(x + w, y + h, x, y + h, r);\n        ctx.arcTo(x, y + h, x, y, r);\n        ctx.arcTo(x, y, x + w, y, r);\n        ctx.closePath();\n      }\n\n      function shadeColor(hex, percent) {\n        const num = parseInt(hex.replace('#', ''), 16);\n        const r = clamp((num >> 16) + percent, 0, 255);\n        const g = clamp(((num >> 8) & 0x00FF) + percent, 0, 255);\n        const b = clamp((num & 0x0000FF) + percent, 0, 255);\n        return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);\n      }\n\n      // ── Game loop ─────────────────────────────────────────\n      let lastTime = 0;\n      function loop(now) {\n        const dt = now - lastTime;\n        lastTime = now;\n        update();\n        render();\n        requestAnimationFrame(loop);\n      }\n\n      // ── Init ──────────────────────────────────────────────\n      window.addEventListener('resize', resize);\n      resize();\n      buildLevel(1);\n      updateHUD();\n      showOverlay('menu');\n      requestAnimationFrame(loop);\n    })();\n    </script>\n  </body>\n</html>\n";
